import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const PaymentPending = () => {
  const navigate = useNavigate();
  const [statusText, setStatusText] = useState("Checking payment status...");

  useEffect(() => {
    const orderId = localStorage.getItem("latestOrderId");

    if (!orderId) {
      navigate("/checkout");
      return;
    }

    const interval = setInterval(async () => {
      try {
        const res = await axios.get(
          `http://localhost:5000/order-status/${orderId}`
        );

        if (res.data.paymentStatus === "approved") {
          clearInterval(interval);
          localStorage.removeItem("latestOrderId");

          setStatusText("Payment Successful ✅");

          setTimeout(() => {
            navigate("/order-success");
          }, 1500);
        }

        if (res.data.paymentStatus === "rejected") {
          clearInterval(interval);
          localStorage.removeItem("latestOrderId");

          setStatusText("Payment not received ❌ Retry Payment");

          setTimeout(() => {
            navigate("/checkout");
          }, 1500);
        }
      } catch (err) {
        console.log("Status check error:", err);
      }
    }, 3000);

    return () => clearInterval(interval);
  }, [navigate]);

  return (
    <div style={container}>
      <div style={card}>
        <h2>{statusText}</h2>
        <p>We are checking your payment.</p>
        <p>Please wait for admin approval.</p>
      </div>
    </div>
  );
};

const container = {
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  minHeight: "80vh",
  padding: "20px"
};

const card = {
  background: "#fff",
  padding: "30px",
  borderRadius: "16px",
  boxShadow: "0 8px 20px rgba(0,0,0,0.1)",
  textAlign: "center",
  maxWidth: "450px",
  width: "100%"
};

export default PaymentPending;
